  ui_story_5030_50300001_88_dialog_content = "<size=45>Ayo ramaikan acaranya!!!</size>",
  ui_story_5030_50300002_1_dialog_content = "Lain!",
  ui_story_5030_50300002_2_dialog_content = "Pergi sedikit cepat ke sana, ya, Jona?",
