  ui_story_5030_50300002_14_dialog_content = "S-Tentu saya punya!",
  ui_story_5030_50300002_15_dialog_content = "Oh?",
  ui_story_5030_50300002_16_dialog_content = "saya mengerti Vice dan Carleen tidak ada hari ini. Tidak heran Anda setuju begitu cepat!",
  ui_story_5030_50300002_17_dialog_content = "I-Bukan itu!!",
  ui_story_5030_50300002_18_dialog_content = "Sigh... Harus kuakui, aku sedikit kecewa.",
  ui_story_5030_50300002_19_dialog_content = "Apakah kamu malu karena Jona ada di sini, sayang?",
