  ui_story_5030_50300002_21_dialog_content = "Yah, kurasa aku akan melepaskanmu... kali ini.",
  ui_story_5030_50300002_22_dialog_content = "Ngomong-ngomong, aku tidak tahu tentang kalian berdua, tapi aku mulai merasa sedikit lapar...",
  ui_story_5030_50300002_23_dialog_content = "Tunggu, bukankah kamu menjalankan kios di sini, PlayerName?",
