  ui_story_5030_50300002_28_dialog_content = "Bukan masalah!",
  ui_story_5030_50300002_29_dialog_content = "Pesan di sini!",
  ui_story_5030_50300002_30_dialog_content = "Saya senang melihat seperti apa selera masakan Anda, PlayerName...",
  ui_story_5030_50300002_31_dialog_content = "Hmm. Tidak buruk, kurasa.",
  ui_story_5030_50300002_32_dialog_content = "Tidak buruk sama sekali!",
