  ui_story_5030_50300002_36_dialog_content = "Ah... Maksudmu toko tempat kita pertama kali bertemu?",
  ui_story_5030_50300002_37_dialog_content = "Ya.",
  ui_story_5030_50300002_38_dialog_content = "Ketika saya melihat Anda menggoda bartender muda itu pada saat itu, saya hampir mengira Anda semacam pecandu alkohol yang mencoba menipu minuman gratis.",
  ui_story_5030_50300002_39_dialog_content = "Sekadar informasi, Anda sendiri tidak tampak begitu normal dengan lebih dari 20 gelas kosong yang duduk di depan Anda, dan Anda terus berteriak untuk meminta lebih...",
  ui_story_5030_50300002_40_dialog_content = "Sejujurnya saya pikir Anda hanya pemabuk jorok tanpa kontrol diri.",
