  ui_story_5030_50300002_42_dialog_content = "\"Teman baik\"?",
  ui_story_5030_50300002_43_dialog_content = "Kedengarannya sangat kekanak-kanakan, sesuatu yang hanya akan dikatakan oleh seorang remaja.",
