  ui_story_5030_50300002_47_dialog_content = "Ya, kedengarannya benar!",
  ui_story_5030_50300002_48_dialog_content = "Dengan memejamkan mata dan memusatkan perhatian pada indera peraba kita serta titik kontak antara tangan kita dan setir...",
  ui_story_5030_50300002_49_dialog_content = "Kami bisa merasakan hubungan yang lebih dalam antara tubuh kami dan mesin kami.",
  ui_story_5030_50300002_50_dialog_content = "Berkat ingatan otot itulah kami dapat mengendarai raksasa kami itu.",
  ui_story_5030_50300002_51_dialog_content = "Ya... Itu adalah ledakan!",
  ui_story_5030_50300002_52_dialog_content = "Kedengarannya sangat berbahaya!",
  ui_story_5030_50300002_53_dialog_content = "Bagi kami, bahaya dan kesenangan adalah dua sisi mata uang yang sama.",
  ui_story_5030_50300002_54_dialog_content = "Sekarang setelah Anda menyebutkannya, saat kami mengalahkan Eclipsites itu juga cukup menyenangkan.",
  ui_story_5030_50300002_55_dialog_content = "Setidaknya itu terdengar jauh lebih normal daripada mengemudi dengan mata tertutup...",
  ui_story_5030_50300002_56_dialog_content = "Oh, maksudmu saat kita sepakat untuk bertarung hanya dengan satu tangan?",
  ui_story_5030_50300002_57_dialog_content = "Lupakan aku mengatakan apa-apa.",
  ui_story_5030_50300002_58_dialog_content = "Ya, itu waktu yang sangat bagus.",
  ui_story_5030_50300002_59_dialog_content = "Tentu, kami mendapat sedikit pukulan untuk itu, tetapi adrenalin benar-benar tak tertahankan.",
  ui_story_5030_50300002_60_dialog_content = "Saya sangat setuju. Dan bir dingin yang kami minum setelah itu benar-benar melengkapi pengalaman itu.",
