  ui_story_5030_50300002_62_dialog_content = "Sayang sekali?",
  ui_story_5030_50300002_63_dialog_content = "Ah! Maaf, saya tidak punya minuman beralkohol di sini.",
  ui_story_5030_50300002_64_dialog_content = "Hmm? Tidak sayang, saya akan mengatakan bahwa itu sangat disayangkan Jona di sini tidak menikmati menggoda dengan anak laki-laki.",
