  ui_story_5030_50300002_66_dialog_content = "Setuju.",
  ui_story_5030_50300002_67_dialog_content = "Saya tidak peduli untuk berteman dengan remaja bodoh ... tidak seperti Anda.",
  ui_story_5030_50300002_68_dialog_content = "Astaga...",
  ui_story_5030_50300002_69_dialog_content = "Hal favorit saya adalah melihat mereka tersipu ketika mereka mencoba untuk tetap tenang!",
