  ui_story_5030_50300003_4_dialog_content = "Aku, aku...",
  ui_story_5030_50300003_5_dialog_content = "Saya tidak berpikir ada yang bisa mendengar Anda ...",
  ui_story_5030_50300003_6_dialog_content = "Tidak ada orang di sekitarnya sekarang, Merylt! Ini adalah kesempatan sekali seumur hidup!",
  ui_story_5030_50300003_7_dialog_content = "Saya tahu saya tahu...",
  ui_story_5030_50300003_8_dialog_content = "Yah, anu...",
  ui_story_5030_50300003_9_dialog_content = "PlayerName!",
  ui_story_5030_50300003_10_dialog_content = "Oh? Hei, kalian bertiga! Apa yang dapat saya bantu?",
  ui_story_5030_50300003_11_dialog_content = "Tunggu... Kau terlihat sangat familiar...",
  ui_story_5030_50300003_12_dialog_content = "Ya! Kita pernah bertemu sekali sebelumnya di dek, bukan?",
  ui_story_5030_50300003_13_dialog_content = "Rainbow bilang kau datang untuk membantu sirkus. Apakah itu benar?",
  ui_story_5030_50300003_14_dialog_content = "I-Itu dia! Anda benar sekali!",
  ui_story_5030_50300003_15_dialog_content = "Hei, uh, hanya di antara kita... Apa kau benar-benar mengincar Pot Sihir?",
  ui_story_5030_50300003_16_dialog_content = "Hehehehe! Tenang, ya!",
  ui_story_5030_50300003_17_dialog_content = "Kami di sini untuk membantu Anda mengamankan pot itu, bukan?",
  ui_story_5030_50300003_18_dialog_content = "Tolong aku?",
  ui_story_5030_50300003_19_dialog_content = "Tunggu sebentar... Kenapa kamu tiba-tiba menawarkan bantuan?",
  ui_story_5030_50300003_20_dialog_content = "Juga... Bagaimana tepatnya kamu berencana membantuku?",
  ui_story_5030_50300003_21_dialog_content = "Anda tidak berencana menggunakan saya sebagai salah satu bahan utama dalam kaldu atau apapun... Benar?",
  ui_story_5030_50300003_22_dialog_content = "Tentu saja tidak! Monster macam apa yang kamu bawa untuk kami?!",
  ui_story_5030_50300003_23_dialog_content = "Rencana kami jauh lebih teknis dari itu!",
  ui_story_5030_50300003_24_dialog_content = "Yah, saya tidak bisa mengatakan saya tidak memiliki keraguan ... Tapi saya rasa tidak ada salahnya untuk mendengar kalian keluar ...",
  ui_story_5030_50300003_25_dialog_content = "Ha ha! Itulah semangat!",
  ui_story_5030_50300003_26_dialog_content = "Saya pikir sudah waktunya untuk berbagi cerita itu dengan teman kita di sini, Merylt. Apakah Anda tidak setuju?",
  ui_story_5030_50300003_27_dialog_content = "Eh... Cerita? Cerita apa?",
  ui_story_5030_50300003_28_dialog_content = "Hanya sedikit konteks, sehingga Anda sepenuhnya menghargai upaya yang telah kami lakukan untuk membantu Anda, itu saja!",
  ui_story_5030_50300003_29_dialog_content = "Ahem! Silakan, Merylt! Ceritakan padanya!",
  ui_story_5030_50300003_30_dialog_content = "Uh oh...!",
  ui_story_5030_50300003_31_dialog_content = "Hai! Anda baik-baik saja di sekitar PlayerName beberapa saat yang lalu, jadi mengapa Anda tiba-tiba diam sekarang?!",
  ui_story_5030_50300003_32_dialog_content = "Ssst! Biarkan dia bercerita, ya?",
  ui_story_5030_50300003_33_dialog_content = "AA lama, lama sekali...",
  ui_story_5030_50300003_34_dialog_content = "Di sudut Astra yang jauh dan tersembunyi, pernah ada seorang ratu yang brutal.",
  ui_story_5030_50300003_35_dialog_content = "Sang ratu telah memerintah tempat ini selama beberapa dekade, dan rakyatnya telah menjalani kehidupan yang damai dan mandiri di bawah pemerintahannya.",
  ui_story_5030_50300003_36_dialog_content = "Tapi ketika ratu berusia enam puluh tahun... Topeng itu terlepas, dan kedamaian palsu mereka menyertainya.",
  ui_story_5030_50300003_37_dialog_content = "Bagaimana ini bisa terjadi?! Tidak peduli apa yang saya lakukan, saya tidak bisa menghilangkan kerutan ini!",
  ui_story_5030_50300003_38_dialog_content = "Tidak... Aku tidak bisa menjadi tua seperti ini...",
  ui_story_5030_50300003_39_dialog_content = "Orang-orang saya hanya bisa menjalani kehidupan yang bahagia dan damai di bawah pemerintahan saya!",
  ui_story_5030_50300003_40_dialog_content = "Katakan padaku! Apa yang harus saya lakukan untuk memperpanjang hidup saya dan pemerintahan saya atas tanah ini?",
  ui_story_5030_50300003_41_dialog_content = "Oh!",
  ui_story_5030_50300003_42_dialog_content = "Ada jalan...",
  ui_story_5030_50300003_43_dialog_content = "Teknik terlarang yang hanya disebutkan dalam legenda...",
  ui_story_5030_50300003_44_dialog_content = "Dengan membenamkan diri dalam darah kehidupan anak laki-laki dan perempuan...",
  ui_story_5030_50300003_45_dialog_content = "Dan meninggalkan makanan demi esensi awet muda mereka yang berharga...",
  ui_story_5030_50300003_46_dialog_content = "Sejak hari itu, kehidupan rakyatnya berubah selamanya.",
  ui_story_5030_50300003_47_dialog_content = "Anak-anak mulai menghilang di depan mata mereka, dan kekacauan segera melanda negeri itu.",
  ui_story_5030_50300003_48_dialog_content = "Apakah tidak ada yang bisa menghentikan kegilaan itu? Tidak ada sama sekali?",
  ui_story_5030_50300003_49_dialog_content = "Jawabannya segera mulai terdengar dari lubuk hati setiap orang yang selamat di kerajaan...",
  ui_story_5030_50300003_50_dialog_content = "Melawan! Memberontak! Hanya dengan menggulingkan ratu jahat, mereka akhirnya tahu kedamaian sekali lagi!",
  ui_story_5030_50300003_51_dialog_content = "...",
  ui_story_5030_50300003_52_dialog_content = "...",
  ui_story_5030_50300003_53_dialog_content = "Dan benar saja, tirani sang ratu akhirnya dihentikan oleh orang-orang yang dengan putus asa dia berusaha untuk terus memerintah.",
  ui_story_5030_50300003_54_dialog_content = "Pada waktunya, senyum muncul kembali di wajah anak-anak, saat kedamaian dan keamanan kembali ke kerajaan sekali lagi.",
  ui_story_5030_50300003_55_dialog_content = "Namun…",
  ui_story_5030_50300003_56_dialog_content = "Meskipun ambisi ratu untuk hidup abadi dipenuhi dengan kekerasan dan teror...",
  ui_story_5030_50300003_57_dialog_content = "Mereka yang memiliki pikiran lebih tajam dapat belajar sesuatu yang berharga dari teladannya...",
  ui_story_5030_50300003_58_dialog_content = "Seni ekstraksi.",
  ui_story_5030_50300003_59_dialog_content = "Dari tanaman, kami dapat mengekstrak esensi mereka dan membuat segala macam bumbu dan bahan.",
  ui_story_5030_50300003_60_dialog_content = "Ini adalah hadiah yang kami tawarkan kepada Anda hari ini.",
  ui_story_5030_50300003_61_dialog_content = "Luar biasa... Merylt benar-benar mampu menceritakan keseluruhan cerita di depan PlayerName tanpa henti!",
  ui_story_5030_50300003_62_dialog_content = "Ini panggilan untuk perayaan!",
  ui_story_5030_50300003_63_dialog_content = "Di Sini! Ambil bau!",
  ui_story_5030_50300003_64_dialog_content = "T-Tunggu sebentar! Jangan menatapku seperti itu! Ini membuatku takut!",
  ui_story_5030_50300003_65_dialog_content = "Jangan salah paham, aku bersyukur atas hadiahnya, tapi aku hanya harus memastikan...",
  ui_story_5030_50300003_66_dialog_content = "I-Itu cerita tentang ratu jahat dan apa yang dia lakukan pada anak-anak itu... Ini bukan berdasarkan kisah nyata, kan?",
  ui_story_5030_50300003_66X_dialog_content = "Kisah yang Anda ceritakan ini terlalu menakutkan!",
  ui_story_5030_50300003_67_dialog_content = "Siapa yang bisa mengatakan? Bagaimanapun, selalu ada kebenaran yang tersembunyi di setiap legenda...",
  ui_story_5030_50300003_68_dialog_content = "Ngomong-ngomong, kami membawakanmu hadiahmu, jadi cepat ambil, oke?",
  ui_story_5030_50300003_69_dialog_content = "C-Mungkinkah...",
  ui_story_5030_50300003_70_dialog_content = "Mungkinkah... kau tidak menyukai hadiah kami?",
  ui_story_5030_50300003_71_dialog_content = "Ah! T-Tidak, aku menyukainya!",
  ui_story_5030_50300003_72_dialog_content = "Saya hanya bertanya tentang cerita, itu saja!",
  ui_story_5030_50300003_73_dialog_content = "Maksudku, itu cukup menakutkan.",
  ui_story_5030_50300003_74_dialog_content = "Kau ingin aku menciumnya, kan? Ini dia...",
  ui_story_5030_50300003_75_dialog_content = "Tunggu, ini baunya luar biasa!",
  ui_story_5030_50300003_76_dialog_content = "Ya, ya!",
  ui_story_5030_50300003_77_dialog_content = "Meskipun, saya masih harus bertanya ... Tanaman apa yang Anda gunakan untuk membuat ini?",
  ui_story_5030_50300003_78_dialog_content = "Saya merasa seperti saya tidak akan dapat menggunakannya dengan benar kecuali saya tahu persis terbuat dari apa.",
  ui_story_5030_50300003_79_dialog_content = "Orang-orang akan memakannya dalam masakan saya, jadi saya harus menganggap hal semacam ini dengan serius.",
  ui_story_5030_50300003_80_dialog_content = "Hehe!",
  ui_story_5030_50300003_81_dialog_content = "Butuh waktu hampir satu hari, tapi untungnya... Sepertinya tidak ada hewan yang dirugikan dalam pembuatan bumbu itu!",
  ui_story_5030_50300003_82_dialog_content = "Fi?",
  ui_story_5030_50300003_83_dialog_content = "Anda telah menguping kami selama ini, bukan?",
  ui_story_5030_50300003_84_dialog_content = "Apa? Bagaimana bisa \"menguping\", padahal ini jelas merupakan ruang publik?",
  ui_story_5030_50300003_85_dialog_content = "Saya baru saja datang untuk mencoba semua suguhan lezat yang dijual. Apakah itu salah?",
  ui_story_5030_50300003_86_dialog_content = "Tetapi untuk memastikan bahwa bumbu yang mereka berikan kepada Anda benar-benar nabati, Anda harus...",
  ui_story_5030_50300003_87_dialog_content = "Anda harus membiarkan saya mengendusnya juga!",
  ui_story_5030_50300003_88_dialog_content = "Hei, twerp! Itu hadiah Merylt untuk PlayerName, jadi simpan sarung tangan kotormu untuk dirimu sendiri!",
  ui_story_5030_50300003_89_dialog_content = "*Menangis* Tapi... Tapi...!",
  ui_story_5030_50300003_90_dialog_content = "(Apakah dia benar-benar mengeluarkan air mata palsu karena ini?!)",
  ui_story_5030_50300003_91_dialog_content = "Aku... Aku hanya ingin sedikit mengendus, itu saja... Aku tidak akan pernah mencurinya atau apapun...",
  ui_story_5030_50300003_92_dialog_content = "Urgh... Kenapa, dasar anak nakal yang menjengkelkan!",
  ui_story_5030_50300003_93_dialog_content = "Tidak apa-apa, Subli.",
  ui_story_5030_50300003_94_dialog_content = "Silakan dan cium jika Anda suka, Fia.",
  ui_story_5030_50300003_95_dialog_content = "Saya dapat meyakinkan Anda, ini dibuat dengan menggunakan tanaman yang saya kumpulkan dengan susah payah dalam jangka waktu yang lama.",
  ui_story_5030_50300003_96_dialog_content = "Melihat? Baunya luar biasa, bukan?",
  ui_story_5030_50300003_97_dialog_content = "Ya, kau benar!",
  ui_story_5030_50300003_98_dialog_content = "Dan itu memang memiliki semacam wewangian seperti tanaman, juga...",
  ui_story_5030_50300003_99_dialog_content = "Itu menyelesaikannya, PlayerName! Bumbu ini lolos penilaian profesional saya!",
  ui_story_5030_50300003_100_dialog_content = "Saya tidak pernah meminta \"penilaian profesional\" ... Andalah yang tidak akan membiarkannya pergi ...",
  ui_story_5030_50300003_101_dialog_content = "Aku tidak tahu apa yang kamu bicarakan!",
  ui_story_5030_50300003_102_dialog_content = "Bagaimanapun, terima kasih, Merylt.",
  ui_story_5030_50300003_103_dialog_content = "J-Jangan sebutkan itu...!",
  ui_story_5030_50300003_104_dialog_content = "Sekarang mari kita lihat apa pengaruhnya terhadap rasa kaldu saya ketika saya menambahkannya...",
  ui_story_5030_50300003_105_dialog_content = "Hei, bau apa itu?",
  ui_story_5030_50300003_106_dialog_content = "Wow, aromanya sangat lezat…",
  ui_story_5030_50300003_107_dialog_content = "Saya pikir itu datang dari sana! Yuk, kita lihat!",
  ui_story_5030_50300004_1_dialog_content = "Nomor 78! Mie Anda sudah siap!",
  ui_story_5030_50300004_2_dialog_content = "Nomor 78! Nomor 78?",
  ui_story_5030_50300004_3_dialog_content = "Nomor 78, pesanan Anda adalah—",
  ui_story_5030_50300004_4_dialog_content = "Apa kekacauan ini? Tempat ini benar-benar kacau... Saya tidak tahu di mana garis dimulai atau berakhir!",
  ui_story_5030_50300004_5_dialog_content = "M-Maaf soal itu! akhir baris adalah...",
  ui_story_5030_50300004_6_dialog_content = "Sial... Aku juga tidak yakin di mana itu!",
  ui_story_5030_50300004_7_dialog_content = "Bagaimana dengan ini? Anda memberi tahu saya apa yang Anda inginkan, dan saya akan menelepon nomor Anda ketika pesanan Anda sudah siap.",
  ui_story_5030_50300004_8_dialog_content = "Nah, berapa banyak pesanan di depan saya?",
  ui_story_5030_50300004_9_dialog_content = "Biar kulihat...",
  ui_story_5030_50300004_10_dialog_content = "Nah, Anda akan menjadi Nomor 103, jadi... T-Dua puluh perintah, memberi atau menerima.",
  ui_story_5030_50300004_11_dialog_content = "Hai! Apakah Anda mendapatkan pesanan saya salah atau sesuatu?",
  ui_story_5030_50300004_12_dialog_content = "Saya jelas meminta mie sup, tetapi Anda memberi saya mie dengan saus daging!",
  ui_story_5030_50300004_13_dialog_content = "M-Maaf! Biarkan aku membuatkanmu mangkuk lagi...",
  ui_story_5030_50300004_14_dialog_content = "Hai! Tidak memotong garis! Kami sudah menunggu di sini cukup lama, seperti itu!",
  ui_story_5030_50300004_15_dialog_content = "(Semuanya benar-benar berantakan sekarang... Ini buruk!)",
  ui_story_5030_50300004_16_dialog_content = "(Haruskah saya berhenti menerima pesanan baru? Jika saya melakukannya, saya bisa fokus pada pelanggan yang sudah menunggu makanan mereka.)",
  ui_story_5030_50300004_17_dialog_content = "Ini mie Anda.",
  ui_story_5030_50300004_18_dialog_content = "Hmph. Itu lebih seperti itu.",
  ui_story_5030_50300004_19_dialog_content = "Mi Anda juga akan siap segera setelah ketel mendidih.",
  ui_story_5030_50300004_20_dialog_content = "batu matahari! Sedikit lagi, jika Anda mau?",
  ui_story_5030_50300004_21_dialog_content = "Pesanan Anda juga sudah siap. Yang kurang hanyalah toppingnya... Ini dia.",
  ui_story_5030_50300004_22_dialog_content = "Hehe! Rasanya selalu paling enak saat masih segar!",
  ui_story_5030_50300004_23_dialog_content = "Sepertinya kios itu mengeluarkan pesanan sedikit lebih cepat sekarang.",
  ui_story_5030_50300004_24_dialog_content = "Tampaknya seperti itu. Garisnya juga bergerak jauh lebih cepat!",
  ui_story_5030_50300004_25_dialog_content = "...",
  ui_story_5030_50300004_26_dialog_content = "L-Leona?!",
  ui_story_5030_50300004_27_dialog_content = "Mengapa begitu terkejut? Matamu hampir keluar dari rongganya, kau tahu?",
  ui_story_5030_50300004_28_dialog_content = "M-Maaf, aku hanya tidak tahu harus terkejut apa dulu...",
  ui_story_5030_50300004_29_dialog_content = "Melihat Anda mengunjungi tempat ini, atau melihat Anda meminta Sunstone untuk merebus air dengan nafasnya yang menyala-nyala.",
  ui_story_5030_50300004_30_dialog_content = "Tidak masalah bagiku.",
  ui_story_5030_50300004_31_dialog_content = "Saya melihat antrian di warung ini benar-benar tidak terkendali, jadi saya penasaran ingin melihat apa yang diobral.",
  ui_story_5030_50300004_32_dialog_content = "Aku juga tidak berharap melihatmu di sini.",
  ui_story_5030_50300004_33_dialog_content = "Atau melihat Anda meraba-raba dan menggelepar seperti ini. Aku belum pernah melihat sisimu ini sebelumnya.",
  ui_story_5030_50300004_34_dialog_content = "Eh... Hahahaha...",
  ui_story_5030_50300004_35_dialog_content = "Saya hanya sedikit kewalahan dengan banyaknya pelanggan, itu saja.",
  ui_story_5030_50300004_36_dialog_content = "Begitu... Dengan Sunstone membantumu merebus air, efisiensimu akan meningkat pesat.",
  ui_story_5030_50300004_37_dialog_content = "Meskipun... Apakah hanya aku, atau kerumunan di sekitar kios semakin besar?",
  ui_story_5030_50300004_38_dialog_content = "Hei kamu yang disana.",
  ui_story_5030_50300004_39_dialog_content = "Garisnya seperti itu. Apa yang kamu lakukan berkeliaran di sini?",
  ui_story_5030_50300004_40_dialog_content = "Eh, Leona? Menurut saya...",
  ui_story_5030_50300004_41_dialog_content = "Saya pikir mereka di sini untuk menonton \"tindakan bernapas api\" Sunstone.",
  ui_story_5030_50300004_42_dialog_content = "Apa yang menarik dari Sunstone yang menyemburkan api? Ini sangat normal.",
  ui_story_5030_50300004_43_dialog_content = "A-anu...",
  ui_story_5030_50300004_44_dialog_content = "Mungkin bagi Anda, tapi saya rasa tidak semua orang memiliki kesempatan untuk melihat naga asli sebelumnya.",
  ui_story_5030_50300004_45_dialog_content = "Baiklah.",
  ui_story_5030_50300004_46_dialog_content = "Lihat! Naga bernapas api!",
  ui_story_5030_50300004_47_dialog_content = "Pernahkah Anda melihat satu sebelumnya?",
  ui_story_5030_50300004_48_dialog_content = "Tidak! Saya telah mendengar banyak cerita tentang mereka, tetapi ini adalah pertama kalinya saya melihat langsung secara langsung!",
  ui_story_5030_50300004_49_dialog_content = "Ini sangat kecil dan lucu! Pasti masih sangat muda, ya?",
  ui_story_5030_50300004_50_dialog_content = "Jadi Anda menjual mie di sini?",
  ui_story_5030_50300004_51_dialog_content = "Ayo, mari kita mengantre!",
  ui_story_5030_50300004_52_dialog_content = "Ada lebih banyak orang sekarang ...",
  ui_story_5030_50300004_53_dialog_content = "Sepertinya Sunstone benar-benar tahu cara menggambar orang banyak.",
  ui_story_5030_50300004_54_dialog_content = "Hmm…",
  ui_story_5030_50300004_55_dialog_content = "Leona? Bisakah saya meminta bantuan?",
  ui_story_5030_50300004_56_dialog_content = "Ahem, jika Anda tidak memiliki hal lain untuk dilakukan hari ini ...",
  ui_story_5030_50300004_57_dialog_content = "Ya.",
  ui_story_5030_50300004_58_dialog_content = "Yakinlah, saya akan tinggal sampai sedikit kurang sibuk.",
  ui_story_5030_50300004_59_dialog_content = "Sekarang sekarang, jangan membuat mata anjing itu.",
  ui_story_5030_50300004_60_dialog_content = "Pergi mengurus bisnis.",
  ui_story_5030_50300004_61_dialog_content = "Benar.",
  ui_story_5030_50300004_62_dialog_content = "Pelanggan berikutnya, tolong!",
  ui_story_5030_50300004_63_dialog_content = "Jenis apa yang Anda inginkan?",
  ui_story_5030_50300005_1_dialog_content = "Ini rotimu. Ini kamu.",
  ui_story_5030_50300005_2_dialog_content = "Astaga, itu sedikit panas langsung dari oven ...",
  ui_story_5030_50300005_3_dialog_content = "Biarkan saya membungkusnya dengan baik untuk Anda.",
  ui_story_5030_50300005_4_dialog_content = "Hah? Seorang pelanggan menginginkan tanda tangan saya? Tentu saja!",
  ui_story_5030_50300005_5_dialog_content = "Di mana Anda ingin saya tanda tangani?",
  ui_story_5030_50300005_6_dialog_content = "Kami ingin satu juga! Kami juga!",
  ui_story_5030_50300005_7_dialog_content = "Itu bukan masalah, tetapi bisakah saya meminta semua orang untuk sedikit bersabar? Ada garis yang cukup panjang!",
  ui_story_5030_50300005_8_dialog_content = "Anda ingin sepuluh? Saya mengerti...",
  ui_story_5030_50300005_9_dialog_content = "Para tamu yang terhormat, saya yakin Anda telah memahami esensi sejati dari es serut sekarang.",
  ui_story_5030_50300005_10_dialog_content = "Mencoba berbagai rasa es serut tidak hanya akan memperluas wawasan Anda, tetapi juga membantu membangun fisik yang sehat.",
  ui_story_5030_50300005_11_dialog_content = "Wah, benar-benar enak...!",
  ui_story_5030_50300005_12_dialog_content = "Mengapa tertulis \"bergabung dengan kami\" pada tanda Anda?",
  ui_story_5030_50300005_13_dialog_content = "Sejak saya masuk ke pertunjukan es serut, gilingan tidak pernah berhenti berdering.",
  ui_story_5030_50300005_14_dialog_content = "Menjadi franchisee berarti Anda bisa menghasilkan uang sebanyak yang saya lakukan.",
  ui_story_5030_50300005_15_dialog_content = "Pelajari trik perdagangan, tamu terhormat, dan bergabunglah dengan dunia seru es serut!",
  ui_story_5030_50300005_16_dialog_content = "Kedengarannya cukup bagus... Bagaimana kalau kita membeli satu dulu dan mencicipinya?",
  ui_story_5030_50300005_17_dialog_content = "Ya, mari kita coba satu.",
  ui_story_5030_50300005_18_dialog_content = "Ini milikmu.",
  ui_story_5030_50300005_19_dialog_content = "Dan ini milikmu!",
  ui_story_5030_50300005_20_dialog_content = "Jadilah konsumen yang rasional dan kurangi sampah! Mengerti?",
  ui_story_5030_50300005_21_dialog_content = "Barbekyu panggang tangan benar-benar baru!",
  ui_story_5030_50300005_22_dialog_content = "Saya! Beri aku satu juga, tolong!",
  ui_story_5030_50300005_23_dialog_content = "Nah, bisnis terlihat cukup bagus untuk semua orang!",
  ui_story_5030_50300005_24_dialog_content = "Selanjutnya, ini adalah Rainbow dengan beberapa detail lebih lanjut tentang kompetisi!",
  ui_story_5030_50300005_25_dialog_content = "Pemilik kios peringkat teratas saat ini adalah—Tn. Fleur!",
  ui_story_5030_50300005_26_dialog_content = "Ha, itu bukan kejutan. Lihat saja antrean di depan.",
  ui_story_5030_50300005_27_dialog_content = "Berada di urutan kedua—Mr. Kleken!",
  ui_story_5030_50300005_28_dialog_content = "Meskipun es serut tidak diragukan lagi sulit untuk disimpan, keterampilan pemasarannya yang luar biasa telah memberinya hasil yang luar biasa.",
  ui_story_5030_50300005_29_dialog_content = "Di tempat ketiga—Ms. Smokey!",
  ui_story_5030_50300005_30_dialog_content = "Meskipun dia mungkin sedikit menyebalkan, tidak dapat disangkal bahwa bisnisnya sangat bagus!",
  ui_story_5030_50300005_31_dialog_content = "Sepertinya semua orang habis-habisan, hanya untuk mendapatkan Pot Sihir ini!",
  ui_story_5030_50300005_32_dialog_content = "Ups, hampir lupa PlayerName kami!",
  ui_story_5030_50300005_33_dialog_content = "Baik! Sebenarnya, hasil PlayerName juga cukup bagus.",
  ui_story_5030_50300005_34_dialog_content = "Meskipun hasilnya tidak terlalu memukau seperti tiga besar kami, tidak ada keraguan bahwa dengan sedikit kerja keras, kemenangan mungkin terjadi!",
  ui_story_5030_50300005_35_dialog_content = "Eh... Hahaha...!",
  ui_story_5030_50300005_36_dialog_content = "Nah, itulah akhir dari siaran paruh waktu!",
  ui_story_5030_50300005_37_dialog_content = "Saat kita bertemu lagi, saatnya mengumumkan hasil kompetisi!",
  ui_story_5030_50300005_38_dialog_content = "Untuk mendapatkan alat masak misterius itu, dan wujudkan impian Anda!",
  ui_story_5030_50300005_39_dialog_content = "Ayo, semuanya!",
  ui_story_5030_50300005_40_dialog_content = "Langkah tepat dan terlibat!",
  ui_story_5030_50300005_41_dialog_content = "Fiuh... Aku merasakan tekanan.",
  ui_story_5030_50300005_42_dialog_content = "Ada lebih sedikit pelanggan juga, karena Leona kiri.",
  ui_story_5030_50300005_43_dialog_content = "Benar saja, mereka datang jauh-jauh ke sini untuk makan mie hanya untuk menonton naga yang bernapas api itu ...",
  ui_story_5030_50300005_44_dialog_content = "Ini sepertinya tidak berhasil.",
  ui_story_5030_50300005_45_dialog_content = "Kamu memang terlihat sangat khawatir sekarang.",
  ui_story_5030_50300005_46_dialog_content = "Saya ingin tahu, PlayerName, dengan masalah apa Anda terjebak?",
  ui_story_5030_50300005_47_dialog_content = "Hai, Genevieve.",
  ui_story_5030_50300005_48_dialog_content = "Ah, apakah kamu datang untuk mie?",
  ui_story_5030_50300005_49_dialog_content = "Tunggu. Saya mengerti. Anda sedang mencari seseorang, kan?",
  ui_story_5030_50300005_50_dialog_content = "Nah, itu dia...",
  ui_story_5030_50300005_51_dialog_content = "Hei, tahan! Tunggu sebentar!",
  ui_story_5030_50300005_52_dialog_content = "Apa pun yang Anda pikirkan, PlayerName yang malang?",
  ui_story_5030_50300005_53_dialog_content = "Saya di sini hanya untuk membantu Anda.",
  ui_story_5030_50300005_54_dialog_content = "Tolong aku?",
  ui_story_5030_50300005_55_dialog_content = "Ah, aku ingat sekarang. Bukankah kamu juga cukup ahli dengan api...?",
  ui_story_5030_50300005_56_dialog_content = "Membantu Anda merebus air lebih cepat, lalu bilas dan ulangi?",
  ui_story_5030_50300005_57_dialog_content = "Meski begitu, itu hanya pengulangan dari hasil terakhir, bukan peningkatan besar.",
  ui_story_5030_50300005_58_dialog_content = "Anda, Anda harus melihat gambaran yang lebih besar.",
  ui_story_5030_50300005_59_dialog_content = "Orang-orang datang ke sini untuk sesuatu yang segar dan baru, bukan?",
  ui_story_5030_50300005_60_dialog_content = "Pikirkan tentang itu.",
  ui_story_5030_50300005_61_dialog_content = "Bayangkan jika warung Anda tidak hanya menawarkan rezeki, tetapi juga memberikan tambahan untuk pelanggan yang lelah?",
  ui_story_5030_50300005_62_dialog_content = "Apa yang Anda maksud dengan \"tambahan\"?",
  ui_story_5030_50300005_63_dialog_content = "Um, Genevieve, kami berada di wilayah Lumopolis. Ini bukan wilayah Orde Sejati atau Umbraton.",
  ui_story_5030_50300005_64_dialog_content = "Bukankah kita akan ditangkap jika kita bertindak terlalu jauh?",
  ui_story_5030_50300005_65_dialog_content = "Apa?",
  ui_story_5030_50300005_66_dialog_content = "Dengan \"ekstra\", maksud saya layanan pelanggan yang lebih baik seperti line-holding dan pijat!",
  ui_story_5030_50300005_67_dialog_content = "Oh, MEREKA jenis layanan!",
  ui_story_5030_50300005_68_dialog_content = "Saya pikir Anda ingin saya memasukkan beberapa gin atau sesuatu!",
  ui_story_5030_50300005_69_dialog_content = "Mari kita tunggu sampai malam untuk hal semacam itu!",
  ui_story_5030_50300005_70_dialog_content = "Lagi pula, di luar sana terlalu panas untuk diminum, dan tidak mungkin menikmati kelezatan gin.",
  ui_story_5030_50300005_71_dialog_content = "Baiklah, terima kasih atas saran Anda, Genevieve...",
  ui_story_5030_50300005_72_dialog_content = "T-Tapi, masalahnya, saya tidak punya tangan cadangan untuk menawarkan layanan seperti itu?",
  ui_story_5030_50300005_73_dialog_content = "Tidak perlu tanganmu.",
  ui_story_5030_50300005_74_dialog_content = "Saya sudah memiliki banyak \"antek\" yang meminjamkan tangan ...",
  ui_story_5030_50300005_75_dialog_content = "Wanita Genevieve! Wanita Genevieve!!",
  ui_story_5030_50300006_1_dialog_content = "(Ini pasti benar-benar memanggang sekarang.)",
  ui_story_5030_50300006_2_dialog_content = "(Saya hanya merasakan keringat menetes dari dagu saya...)",
  ui_story_5030_50300006_3_dialog_content = "(Jika saya mendengarkan dengan seksama, saya mungkin bisa mendengar setetes keringat itu menyentuh tanah.)",
  ui_story_5030_50300006_4_dialog_content = "(Setidaknya masih ada angin sepoi-sepoi, bahkan di hari yang begitu panas...)",
  ui_story_5030_50300006_5_dialog_content = "(Saya tidak bisa merasakan kelegaan sejuk yang dibawa angin... atau bahkan merasakan angin itu sendiri.)",
  ui_story_5030_50300006_6_dialog_content = "(Eh... Lalu bagaimana aku tahu kalau itu bahkan bertiup?)",
  ui_story_5030_50300006_7_dialog_content = "(Yah, pasti ketiga daun itu berkibar di udara di depanku.)",
  ui_story_5030_50300006_8_dialog_content = "(Tiga daun... Noda air di tanah. Dan piring yang tidak sengaja pecah oleh seseorang... Eh?)",
  ui_story_5030_50300006_9_dialog_content = "(Sepasang sepatu muncul di tanah. Ujung runcingnya berhenti di depanku...)",
  ui_story_5030_50300006_10_dialog_content = "Tunggu... Jari kaki runcing, berhenti di depan warung ramenku?",
  ui_story_5030_50300006_11_dialog_content = "Jadi itu berarti...",
  ui_story_5030_50300006_12_dialog_content = "Seorang tamu! TAMU yang telah lama ditunggu-tunggu!",
  ui_story_5030_50300006_13_dialog_content = "Tamu yang terhormat, tolong, lihatlah! Lihat mie kami!",
  ui_story_5030_50300006_14_dialog_content = "Bisnis tampaknya tidak terlalu cepat.",
  ui_story_5030_50300006_15_dialog_content = "Eh... Jeno?",
  ui_story_5030_50300006_16_dialog_content = "Anda di sini untuk mie?",
  ui_story_5030_50300006_17_dialog_content = "Atau apakah Anda melakukan putaran sebagai tuan rumah ...?",
  ui_story_5030_50300006_18_dialog_content = "Saya di sini untuk mie.",
  ui_story_5030_50300006_19_dialog_content = "... Oh! Saya mengerti.",
  ui_story_5030_50300006_20_dialog_content = "Dan jenis mie apa yang kamu cari?",
  ui_story_5030_50300006_21_dialog_content = "Tidak banyak orang di sini sekarang, jadi saya bisa membiarkan Anda mencoba semuanya ...",
  ui_story_5030_50300006_22_dialog_content = "Semangkuk mie sup baik-baik saja.",
  ui_story_5030_50300006_23_dialog_content = "Terima kasih.",
  ui_story_5030_50300006_24_dialog_content = "Tentu saja! Segera datang...",
  ui_story_5030_50300006_25_dialog_content = "Jadi apa yang Anda pikirkan? Apakah itu baik?",
  ui_story_5030_50300006_26_dialog_content = "Cukup lezat.",
  ui_story_5030_50300006_27_dialog_content = "Baguslah kalau begitu.",
  ui_story_5030_50300006_28_dialog_content = "Jadi saya tidak mengerti mengapa bisnis Anda sangat lambat sekarang.",
  ui_story_5030_50300006_29_dialog_content = "Tentunya harus ada lebih banyak permintaan untuk hal semacam ini, bukan?",
  ui_story_5030_50300006_30_dialog_content = "Sejujurnya, bisnis tidak begitu buruk sekarang ...",
  ui_story_5030_50300006_31_dialog_content = "Hanya saja para tamu tampak lebih tertarik dengan figuran.",
  ui_story_5030_50300006_32_dialog_content = "Ekstra?",
  ui_story_5030_50300006_33_dialog_content = "Hmm... Mungkin lebih baik mengatakan gimmick untuk menghidupkan bisnis.",
  ui_story_5030_50300006_34_dialog_content = "Seperti naga bernapas api atau layanan pelanggan yang lebih baik. Hal-hal seperti itu.",
  ui_story_5030_50300006_35_dialog_content = "Nah, apakah mie rasanya berbeda?",
  ui_story_5030_50300006_36_dialog_content = "Hampir sama, kurasa. Ramen Anda dan yang dijual sebelumnya sama-sama dibuat dengan cara yang persis sama.",
  ui_story_5030_50300006_37_dialog_content = "Anda pasti punya banyak pelanggan, bukan?",
  ui_story_5030_50300006_38_dialog_content = "Ya. Pasti ada antrean panjang.",
  ui_story_5030_50300006_39_dialog_content = "Anda pasti cemas tentang menyajikan mie untuk setiap pelanggan lebih cepat saat itu, saya kira.",
  ui_story_5030_50300006_40_dialog_content = "Yah, itu memang benar...",
  ui_story_5030_50300006_41_dialog_content = "Hmm... Saya pikir saya mengerti apa yang Anda coba katakan.",
  ui_story_5030_50300006_42_dialog_content = "Karena saya terburu-buru, sulit untuk menghindari kesalahan.",
  ui_story_5030_50300006_43_dialog_content = "Dan karena itu, tidak ada kesempatan untuk membuat porsi itu dengan standar yang sama seperti yang baru saja Anda makan.",
  ui_story_5030_50300006_44_dialog_content = "Tidak... Maksudku, aku pikir kamu harus lebih fokus pada makanan itu sendiri.",
  ui_story_5030_50300006_45_dialog_content = "Stres berurusan dengan antrean panjang hanyalah satu masalah.",
  ui_story_5030_50300006_46_dialog_content = "Tapi intinya adalah Anda tidak bisa melayani orang sebanyak itu.",
  ui_story_5030_50300006_47_dialog_content = "Mungkin. Tetapi mereka tidak memiliki kesabaran untuk menunggu lama.",
  ui_story_5030_50300006_48_dialog_content = "Bagaimana dengan memperingatkan mereka tentang perkiraan waktu tunggu?",
  ui_story_5030_50300006_49_dialog_content = "Pelanggan yang tertarik dengan ekstra akan lebih tidak sabar.",
  ui_story_5030_50300006_50_dialog_content = "menurut saya paradoks...",
  ui_story_5030_50300006_51_dialog_content = "Anda tahu, intinya adalah saya ingin mendapatkan pot itu. Dan untuk itu terjadi, semakin banyak penjualan semakin baik.",
  ui_story_5030_50300006_52_dialog_content = "Jadi Anda pikir ekstra hanyalah sesuatu yang harus Anda lakukan.",
  ui_story_5030_50300006_53_dialog_content = "Tapi bisakah Anda menjamin bahwa semua orang yang tertarik dengan ekstra benar-benar membeli mie Anda?",
  ui_story_5030_50300006_54_dialog_content = "...",
  ui_story_5030_50300006_55_dialog_content = "Yah, aku... Tidak.",
  ui_story_5030_50300006_56_dialog_content = "Hanya saja aku semakin bingung ketika melihat begitu banyak orang menunggu.",
  ui_story_5030_50300006_57_dialog_content = "Dan sedikit cemas.",
  ui_story_5030_50300006_58_dialog_content = "Yang bisa saya pikirkan hanyalah menyelesaikan satu mangkuk, dan kemudian mangkuk berikutnya, dan satu lagi setelah itu...",
  ui_story_5030_50300006_59_dialog_content = "Saya benar-benar bersungguh-sungguh ketika saya mengatakan semangkuk mie di depan saya ini enak.",
  ui_story_5030_50300006_60_dialog_content = "Saya tidak berani mengatakan, \"kepala dingin menghasilkan mie panas.\"",
  ui_story_5030_50300006_61_dialog_content = "Atau \"Fokus pada makanan, lupakan dunia,\" slogan-slogan basi tersebut.",
  ui_story_5030_50300006_62_dialog_content = "Nah, yang ingin saya katakan adalah: Semangkuk mie ini cukup enak.",
  ui_story_5030_50300006_63_dialog_content = "Jika saya tahu seseorang berniat membuka restoran di masa mendatang, saya akan mengarahkan mereka ke arah Anda untuk tips membuat mie.",
  ui_story_5030_50300006_64_dialog_content = "Hmm…",
  ui_story_5030_50300006_65_dialog_content = "Terima kasih, Jeno.",
  ui_story_5030_50300006_66_dialog_content = "Apakah ini yang Anda pikirkan saat pertama kali tampil?",
  ui_story_5030_50300006_67_dialog_content = "Anda tahu, tidak memperhatikan ukuran penonton tetapi hanya fokus pada keajaiban?",
  ui_story_5030_50300006_68_dialog_content = "Ya.",
  ui_story_5030_50300006_69_dialog_content = "Sihir adalah hidupku. Saya tidak peduli tentang hal lain.",
  ui_story_5030_50300006_70_dialog_content = "Harus saya katakan, sikap seperti itu sangat berpengaruh.",
  ui_story_5030_50300006_71_dialog_content = "Anda punya beberapa tamu lagi.",
  ui_story_5030_50300006_72_dialog_content = "Jika Anda akan permisi. Saya menantikan keajaiban Anda.",
  ui_story_5030_50300006_73_dialog_content = "Fokus pada makanan itu sendiri...?",
  ui_story_5030_50300006_74_dialog_content = "Mie itu enak. Ambil bahan-bahan ini sebagai ucapan terima kasih!",
  ui_story_5030_50300006_75_dialog_content = "Saya dapat meyakinkan Anda, ini dibuat dengan menggunakan tanaman yang saya kumpulkan dengan susah payah dalam jangka waktu yang lama.",
  ui_story_5030_50300006_76_dialog_content = "Melihat? Baunya luar biasa, bukan?",
  ui_story_5030_50300006_77_dialog_content = "Buku masak rahasia ini untuk Anda!",
  ui_story_5030_50300006_78_dialog_content = "Anda pasti tidak akan mengecewakan kami, bukan, PlayerName?",
  ui_story_5030_50300006_79_dialog_content = "Ah! Saya mengerti!",
  ui_story_5030_50300007_1_dialog_content = "Apa kah kamu mendengar? Legenda absolut itu juga akan ambil bagian!",
  ui_story_5030_50300007_2_dialog_content = "Paman Johnny? Maksudmu Paman Johnny datang ke sini, secara pribadi?!",
  ui_story_5030_50300007_3_dialog_content = "Tidak, tidak... Kurasa namanya seperti Noodle God.",
  ui_story_5030_50300007_4_dialog_content = "Teman saya pergi untuk mencoba warung Noodle God. Putusan: dia tidak pernah makan mie yang begitu enak sepanjang hidupnya!",
  ui_story_5030_50300007_5_dialog_content = "Betulkah? Itu memang terdengar ilahi. Saya pikir saya ingin mencoba beberapa juga.",
  ui_story_5030_50300007_6_dialog_content = "Lihat, di sebelah sana—",
  ui_story_5030_50300007_7_dialog_content = "203! Itu aku! Nomor pesanan 203!",
  ui_story_5030_50300007_8_dialog_content = "Anda telah tertipu, sobat. Saya pikir Anda akan menemukan bahwa saya 203.",
  ui_story_5030_50300007_9_dialog_content = "Melihat 203-an bertarung habis-habisan, mengapa tidak memberikannya saja kepada saya? aku 204!",
  ui_story_5030_50300007_10_dialog_content = "Wow... Terlalu banyak orang yang mengantri...?",
  ui_story_5030_50300007_11_dialog_content = "(Tanganku sakit...)",
  ui_story_5030_50300007_12_dialog_content = "(Aku bahkan tidak yakin bisa melakukan sesuatu yang mendasar seperti menyerahkan mangkuk...)",
  ui_story_5030_50300007_13_dialog_content = "(Tapi jika bukan karena itu...)",
  ui_story_5030_50300007_14_dialog_content = "(Untuk impian terakhir saya!)",
  ui_story_5030_50300007_15_dialog_content = "(Untuk memungkinkan semua orang di Cloud Gardens dan Colossus menikmati mie yang enak dan nyaman!)",
  ui_story_5030_50300007_16_dialog_content = "-Hai! 204! Anda bangun!",
  ui_story_5030_50300007_17_dialog_content = "Wow! Sepertinya ramai di sekitar sini, PlayerName!",
  ui_story_5030_50300007_18_dialog_content = "Eh, kamu di sini untuk mie juga, Rainbow?",
  ui_story_5030_50300007_19_dialog_content = "Tidak kali ini. Saya di sini untuk membuat pengumuman kompetisi!",
  ui_story_5030_50300007_20_dialog_content = "SELAMAT, PlayerName!",
  ui_story_5030_50300007_21_dialog_content = "Mengucapkan selamat padaku?",
  ui_story_5030_50300007_22_dialog_content = "Apakah Anda memberi tahu saya bahwa saya berhasil—",
  ui_story_5030_50300007_23_dialog_content = "Anda sekarang berada di posisi kedua!",
  ui_story_5030_50300007_24_dialog_content = "... Apa sebenarnya yang Anda ucapkan selamat kepada saya?",
  ui_story_5030_50300007_25_dialog_content = "Hah? Anda berada di urutan keempat di akhir putaran terakhir!",
  ui_story_5030_50300007_26_dialog_content = "Itu adalah kemajuan yang pantas untuk ucapan selamat jika memang ada!",
  ui_story_5030_50300007_27_dialog_content = "Nah, jika Anda bersikeras mengatakannya seperti itu ...",
  ui_story_5030_50300007_28_dialog_content = "Siapa di tempat pertama?",
  ui_story_5030_50300007_29_dialog_content = "Hanya pendiri kerajaan roti—Mr. Fleur!",
  ui_story_5030_50300007_30_dialog_content = "Kami turun ke setengah jam terakhir kompetisi. Bisakah kerja keras membantu PlayerName melewati batas?",
  ui_story_5030_50300007_31_dialog_content = "Aku pasti akan mencoba.",
  ui_story_5030_50300007_32_dialog_content = "Apakah sudah siap? Apakah saya sudah bangun? aku 205!",
  ui_story_5030_50300007_33_dialog_content = "Satu detik, hampir selesai!",
  ui_story_5030_50300007_34_dialog_content = "Menakjubkan! Meskipun dia sedang mengobrol dengan tuan rumah, tangannya tidak pernah berhenti!",
  ui_story_5030_50300007_35_dialog_content = "Apakah ini bakat rahasia Dewa Mie?",
  ui_story_5030_50300007_36_dialog_content = "Dewa mie?",
  ui_story_5030_50300007_37_dialog_content = "Mengapa, halo di sana!",
  ui_story_5030_50300007_38_dialog_content = "Dapatkah saya bertanya siapa yang Anda maksud dengan \"Noodle God\"?",
  ui_story_5030_50300007_39_dialog_content = "Eh, pemilik warung mie ini saja.",
  ui_story_5030_50300007_40_dialog_content = "Wow—sekarang ITU antrean panjang!",
  ui_story_5030_50300007_41_dialog_content = "Itu hanya karena mie nya sangat enak.",
  ui_story_5030_50300007_42_dialog_content = "Dewa mie? Pff...",
  ui_story_5030_50300007_43_dialog_content = "Jelas hanya Anzu dan Momo yang layak mendapat julukan seperti itu!",
  ui_story_5030_50300007_44_dialog_content = "Saya pikir saya lebih baik melihat lebih dekat pada orang ini, lihat betapa terampilnya dia!",
  ui_story_5030_50300007_45_dialog_content = "Lanjut! Hai, yang di sana! Rasa apa yang kamu inginkan—",
  ui_story_5030_50300007_46_dialog_content = "... Yao?!",
  ui_story_5030_50300007_47_dialog_content = "Wah sekarang! Astaga...!",
  ui_story_5030_50300007_48_dialog_content = "Tunggu sebentar... Apakah Anda memberi tahu saya bahwa ANDA adalah Dewa Mie yang mereka bicarakan?",
  ui_story_5030_50300007_49_dialog_content = "Dengar, aku mungkin orang yang memanggil semua orang seperti itu tapi, tapi... Bukannya aku mempromosikan diriku seperti itu!",
  ui_story_5030_50300007_50_dialog_content = "Jadi benar-benar masakanmu yang membuat semua orang terkesan?",
  ui_story_5030_50300007_51_dialog_content = "Maksudku, ya? Mungkin...",
  ui_story_5030_50300007_52_dialog_content = "Apakah datang ke sini bagian dari perjalanan Anda?",
  ui_story_5030_50300007_53_dialog_content = "Ya! Saya ingin melihat-lihat!",
  ui_story_5030_50300007_54_dialog_content = "Tapi harus kuakui ini pemandangan yang agak aneh—kamu, sendirian, memasak mie!",
  ui_story_5030_50300007_55_dialog_content = "Ohh! Jadi untuk Panci Sihir itu, ya? Tidak heran saya baru saja melihat Kleken di sana...",
  ui_story_5030_50300007_56_dialog_content = "Wow, motivasi mulia yang tak terduga untuk menang, PlayerName!",
  ui_story_5030_50300007_57_dialog_content = "Woo... Boo-hoo... Aku merasakanmu. Jangan katakan lagi, PlayerName!",
  ui_story_5030_50300007_58_dialog_content = "Harus ada setidaknya 20 orang di belakangku. Berapa banyak lagi pesanan yang bisa Anda buat?",
  ui_story_5030_50300007_59_dialog_content = "Hmm... bisakah kamu mengatur 87?",
  ui_story_5030_50300007_60_dialog_content = "Yakinlah, 87 mangkuk ini—",
  ui_story_5030_50300007_61_dialog_content = "SEMUA SEKARANG TERKONTRAK OLEH SAYA!",
  ui_story_5030_50300007_62_dialog_content = "Siapa pemasok mie dan toppingnya?",
  ui_story_5030_50300007_63_dialog_content = "Biarkan aku membeli semua bahan mentah juga!",
  ui_story_5030_50300007_64_dialog_content = "Yao, dengar, aku...",
  ui_story_5030_50300007_65_dialog_content = "Ehh, tidak perlu berterima kasih padaku!",
  ui_story_5030_50300007_66_dialog_content = "Untuk mimpi yang begitu besar... Aku hanya harus membantu!",
  ui_story_5030_50300007_67_dialog_content = "Ditambah aku sangat kaya, haha!",
  ui_story_5030_50300007_68_dialog_content = "Hitung mundur terakhir dimulai—!",
  ui_story_5030_50300007_69_dialog_content = "Wow, setiap kontestan melangkah!",
  ui_story_5030_50300007_70_dialog_content = "Pada saat yang sangat menegangkan ini—TIGA!",
  ui_story_5030_50300007_71_dialog_content = "Rincian kontak tertulis Kleken untuk investasi tentakelnya sendiri!",
  ui_story_5030_50300007_72_dialog_content = "Ini adalah penantian yang menggigit kuku untuk hasilnya — DUA!",
  ui_story_5030_50300007_73_dialog_content = "Fleur sekali lagi memamerkan senyum kemenangan merek dagang itu kepada para penggemarnya!",
  ui_story_5030_50300007_74_dialog_content = "Kegembiraannya hampir terlalu banyak untuk ditangani—SATU!",
  ui_story_5030_50300007_75_dialog_content = "Dengan ini saya menyatakan juara pertempuran ini untuk Pot Sihir menjadi—",
  ui_story_5030_50300007_76_dialog_content = "PlayerName!",
  ui_story_5030_50300007_77_dialog_content = "PlayerName, yang menjual mie dalam jumlah yang luar biasa, semuanya untuk mengejar impian besarnya!",
  ui_story_5030_50300007_78_dialog_content = "Mari kita ucapkan selamat kepada PlayerName karena memenangkan Pot Sihir yang misterius dan menarik ini!",
  ui_story_5030_50300007_79_dialog_content = "Selamat, PlayerName.",
  ui_story_5030_50300007_80_dialog_content = "Jadi PlayerName menang!",
  ui_story_5030_50300007_81_dialog_content = "Apakah Anda tahu cara menggunakannya?",
  ui_story_5030_50300007_82_dialog_content = "Err... Terima kasih semuanya.",
  ui_story_5030_50300007_83_dialog_content = "Saya rasa saya perlu meluangkan waktu untuk menjelajahi cara menggunakannya.",
  ui_story_5030_50300007_84_dialog_content = "Sepertinya aku pernah melihat alat masak seperti ini sebelumnya, tapi panci ini...",
  ui_story_5030_50300007_85_dialog_content = "Eh, Anda tidak tahu cara menggunakannya, bukan?",
  ui_story_5030_50300007_86_dialog_content = "Aku, aku hanya perlu menyegarkan ingatanku!",
  ui_story_5030_50300007_87_dialog_content = "(Bagaimana tepatnya saya mengaktifkan masak otomatis?)",
  ui_story_5030_50300007_88_dialog_content = "(Apakah saya akan terlihat sedikit bodoh jika saya mencoba merasakannya?)",
  ui_story_5030_50300007_89_dialog_content = "Bisakah saya melihat-lihat?",
  ui_story_5030_50300007_90_dialog_content = "Tentu saja.",
  ui_story_5030_50300007_91_dialog_content = "Saya tidak punya ide. Ini benar-benar berbeda dengan peralatan masak lainnya yang pernah saya lihat...",
  ui_story_5030_50300007_92_dialog_content = "Um... Tapi strukturnya yang indah benar-benar membuat orang ingin tahu cara kerjanya.",
  ui_story_5030_50300007_93_dialog_content = "PlayerName, ketika Anda telah mencapai impian Anda, bisakah saya meminjam alat masak ini selama beberapa hari?",
  ui_story_5030_50300007_94_dialog_content = "Tidak masalah! Saya hanya harus mencari tahu cara kerjanya, pertama ...",
  ui_story_5030_50300007_95_dialog_content = "Saya rasa itu membutuhkan semacam dorongan eksternal untuk memulai.",
  ui_story_5030_50300007_96_dialog_content = "Api? Apakah itu membutuhkan api?",
  ui_story_5030_50300007_97_dialog_content = "Tidak ada salahnya untuk mencoba?",
  ui_story_5030_50300007_98_dialog_content = "... Itu terlalu jauh, bukan?!",
  ui_story_5030_50300007_99_dialog_content = "Tapi lihat, tidak ada kerusakan.",
  ui_story_5030_50300007_100_dialog_content = "Bagaimana kalau... mencoba air?",
  ui_story_5030_50300007_101_dialog_content = "...",
  ui_story_5030_50300007_102_dialog_content = "Membakar dengan gelombang laut!",
  ui_story_5030_50300007_103_dialog_content = "Itu tetap diam.",
  ui_story_5030_50300007_104_dialog_content = "Er, mungkin perlu kekuatan yang lebih lembut dan lebih terkontrol?",
  ui_story_5030_50300007_105_dialog_content = "Aku di sini!",
  ui_story_5030_50300007_106_dialog_content = "Tampaknya keras seperti batu.",
  ui_story_5030_50300007_107_dialog_content = "Ce-ce...",
  ui_story_5030_50300007_108_dialog_content = "Anda tidak dapat menggunakan pemikiran modern untuk memahami hal-hal kuno semacam ini dari reruntuhan...",
  ui_story_5030_50300007_109_dialog_content = "Tapi bagaimana kita akan tahu jika kita tidak mencoba?",
  ui_story_5030_50300007_110_dialog_content = "Nah... Coba serang dengan Lumina?",
  ui_story_5030_50300007_111_dialog_content = "Aku, aku...",
  ui_story_5030_50300007_112_dialog_content = "Benar saja, tidak ada dadu ...",
  ui_story_5030_50300007_113_dialog_content = "Apakah Paman Johnny benar-benar pernah menggunakan pot ini?",
  ui_story_5030_50300007_114_dialog_content = "Saya tidak berpikir alat legendaris semacam ini sangat bisa diandalkan!",
  ui_story_5030_50300007_115_dialog_content = "Fungsi \"memasak otomatis\" ini... Tidak seperti moniker saya barusan, bukan? Hanya semacam retorika berlebihan yang keterlaluan?",
  ui_story_5030_50300007_116_dialog_content = "Ha… Hahaha!",
  ui_story_5030_50300007_117_dialog_content = "Uh, ini... Aku hanya dibayar untuk membaca naskahnya!",
  ui_story_5030_50300007_118_dialog_content = "Maksud saya adalah, mungkin bahkan tidak memiliki fungsi ini!",
  ui_story_5030_50300007_119_dialog_content = "Aku merasa kasihan padamu, prajurit yang manis.",
  ui_story_5030_50300007_120_dialog_content = "J-jika Anda tidak keberatan, PlayerName, II bisa...",
  ui_story_5030_50300007_121_dialog_content = "Aku bisa membawanya kembali ke Kota Gannon. Lihat apakah Petugas Gronru dan nasibnya bisa menyelesaikannya...",
  ui_story_5030_50300007_122_dialog_content = "I-Mereka tahu banyak tentang relik yang ditemukan di reruntuhan...",
  ui_story_5030_50300007_123_dialog_content = "Sepertinya kita tidak punya banyak pilihan sekarang.",
  ui_story_5030_50300007_124_dialog_content = "Dan sebagainya PlayerName sampai pada akhir perjalanan mie-nya.",
  ui_story_5030_50300007_125_dialog_content = "Dia mengklaim bahwa, meskipun hadiahnya telah diambil untuk belajar, dia menemukan seluruh pengalaman itu menarik.",
  ui_story_5030_50300007_126_dialog_content = "Bagaimanapun, ia telah menguasai keterampilan memasak dengan hati, yang menghasilkan ulasan bagus dari pelanggan.",
  ui_story_5030_50300007_127_dialog_content = "Dan keji Kleken kembali mencuri banyak ide bagus tentang pengoptimalan es serut.",
  ui_story_5030_50300007_128_dialog_content = "Beberapa orang bahkan sangat ingin bergabung dengan bisnis es serutnya!",
  ui_story_5030_50300007_129_dialog_content = "Mengapa, itu jelas milikku... Lupakan saja. Kita lihat siapa yang tertawa nanti!",
  ui_story_5030_50300007_130_dialog_content = "Roti Fleur terjual dengan baik, dan para penggemarnya selalu gembira.",
  ui_story_5030_50300007_131_dialog_content = "Semua orang senang, kecuali...",
  ui_story_5030_50300007_132_dialog_content = "Apakah Anda tahu di mana orang itu?",
  ui_story_5030_50300007_133_dialog_content = "Wanita Genevieve! Apakah Anda masih mencari wanita itu?",
  ui_story_5030_50300007_134_dialog_content = "Saya pikir dia sudah pergi. Tidak di sini, bagaimanapun juga.",
  ui_story_5030_50300007_135_dialog_content = "Ha ha ha! Aku tahu itu!",
  ui_story_5030_50300007_136_dialog_content = "Taruhan dia merangkak kembali ke sudut yang tidak jelas untuk menjilat lukanya.",
  ui_story_5030_50300007_137_dialog_content = "Ck, Smokey. Salah satu hari itu untukmu juga?",
  ui_story_5030_50300007_138_dialog_content = "Hei, kamu, apakah tidak ada yang pernah mengajarimu berbisik ketika memfitnah orang lain?",
  ui_story_5030_50300007_139_dialog_content = "…?",
  ui_story_5030_50300007_140_dialog_content = "Bukankah ini? Smokey dari Mimpi yang Gagal?",
  ui_story_5030_50300007_141_dialog_content = "Bagaimana perasaanmu? Tidak menyenangkan, bukan?",
  ui_story_5030_50300007_142_dialog_content = "Yah. Saya tidak terlalu peduli apakah saya mendapatkan pot atau tidak.",
  ui_story_5030_50300007_143_dialog_content = "Saya hanya ingin menemukan tempat yang bagus untuk membakar dengan sungguh-sungguh.",
  ui_story_5030_50300007_144_dialog_content = "Namun yang kalah mencoba untuk tegar dan berani! Betapa lucunya!",
  ui_story_5030_50300007_145_dialog_content = "Bagaimana denganmu?",
  ui_story_5030_50300007_146_dialog_content = "Harus memutar otak untuk memikirkan cara membuatku kalah, lalu dengan sombong berpikir aku benar-benar peduli?",
  ui_story_5030_50300007_147_dialog_content = "Apakah Anda yakin Anda hanya sedikit terobsesi dengan saya, Genevieve?",
  ui_story_5030_50300007_148_dialog_content = "Anda? Siapa yang akan membuang waktu mereka? Kamu pikir kamu siapa?",
  ui_story_5030_50300007_149_dialog_content = "Jika Anda bertanya kepada saya, bahkan lebih lamer untuk menjadi begitu menganggur setiap hari sehingga yang dapat Anda lakukan hanyalah berlari mengejar orang lain.",
  ui_story_5030_50300007_150_dialog_content = "Bukankah begitu, anjing kecil?",
  ui_story_5030_50300007_151_dialog_content = "KENAPA KAMU...!",
  ui_story_5030_50300007_152_dialog_content = "Sampai jumpa untuk saat ini, doggie. Saya pasti akan datang bermain menjemput Anda lain kali.",
  ui_story_5030_50300007_153_dialog_content = "...",
  ui_story_5030_50300007_154_dialog_content = "Oh! Wanita Genevieve! Wanita Genevieve!!",
  ui_story_5030_50300007_155_dialog_content = "Bangun! Ayo! T-Cepat, hubungi dokter—"
